/**
 * @distilled.cloud/onepassword -- 1Password SDK for Effect.
 *
 * One service per 1Password API, each with its own credentials and protocol:
 *
 *   Connect      `connect`      ConnectCredentials      ConnectProtocol
 *   Events       `events`       EventsCredentials       EventsProtocol
 *   Users        `users`        UsersCredentials        UsersProtocol
 *   OAuth        `oauth`        OAuthCredentials        OAuthProtocol
 *   Partnership  `partnership`  PartnershipCredentials  PartnershipProtocol
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI specs. Everything else in
 * this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Onepassword from "@distilled.cloud/onepassword";
 *
 * const vaults = yield* Onepassword.connect.getVaults({});
 * const events = yield* Onepassword.events.getAuditEventsV2({ body: { limit: 100 } });
 * ```
 *
 * @example Per-service path
 * ```ts
 * import * as Connect from "@distilled.cloud/onepassword/connect";
 *
 * const vaults = yield* Connect.getVaults({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ConnectProtocol,
  EventsProtocol,
  UsersProtocol,
  OAuthProtocol,
  PartnershipProtocol,
  type OnepasswordOpError,
  type ConnectOpContext,
  type EventsOpContext,
  type UsersOpContext,
  type OAuthOpContext,
  type PartnershipOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
